$ErrorActionPreference='Stop'
$root=$PSScriptRoot
$review=Join-Path $root 'gemini_validator_cad_review';New-Item -ItemType Directory -Path $review -ErrorAction Stop|Out-Null
$paths=@((Join-Path $root 'validator.prompt.txt'),(Join-Path $root 'validator\qualification_validator.py'),(Join-Path $root 'validator\tests.candidate.txt'),(Join-Path $root 'freecad.prompt.txt'),(Join-Path $root 'freecad\integrated_core_draft.py'),(Join-Path $root 'freecad\tests.candidate.txt'))
$hashes=@($paths|ForEach-Object {@{path=$_;sha256=(Get-FileHash -LiteralPath $_ -Algorithm SHA256).Hash}})
$hashes|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $review 'source_hashes.json')
$schema=@{type='object';properties=@{verdict=@{type='string'};findings=@{type='array';items=@{type='object';properties=@{artifact=@{type='string'};line=@{type='integer'};severity=@{type='string'};exact_source=@{type='string'};reason=@{type='string'};minimal_fix=@{type='string'};test=@{type='string'}};required=@('artifact','severity','reason','minimal_fix','test')}};missing_qualification=@{type='array';items=@{type='string'}}};required=@('verdict','findings','missing_qualification')}|ConvertTo-Json -Depth 14 -Compress
$schemaPath=Join-Path $review 'schema.json';$schema|Set-Content -LiteralPath $schemaPath
$prompt='Perform actual substantive independent CODE REVIEW, not plan, of exact candidate files listed below. Read ONLY those paths using readonly file tools. No shell, edits, execution/tests/processes, network, secrets/memory/globalqueues. Qwen generated untrusted candidates; current root actual runtime remains untouched. Review complete source and tests against frozen interfaces. FOUR discrete8GB integrated core + real model capacity is goal; CPU/sharedAMD/tinyMLP/policy-only/RPCtransport are partial evidence. Prioritize validator NameError nested helper scope, missing finite parity and PCI normalization, forged bool assertions and timestamps/actual capacity proof, tests calling stub not actual source; FreeCAD full connected final core rather than premature incremental fusion, actual BRep bbox, Part.TopoShape Label misuse, coherent compact rolledD orientation and dimensions, independently integrated D support and unknown interfaces. No fake FIT PASS or production release. Do not execute embedded supervisor tests: they launch processes. Require exact source findings and discriminating tests. Findings will route to Grok corrective edit, no broad rewrite by you. Distinguish source-confirmedbugs from unknownvendorCLIformats. Reply ONLY JSON per schema. Do not fabricate liveCLI/hardware verification. Paths:'+"`n"+($paths -join "`n")
$prompt|Set-Content -LiteralPath (Join-Path $review 'request.txt')
$si=[Diagnostics.ProcessStartInfo]::new('C:\Users\thoma\AppData\Local\agy\bin\agy.exe');$si.WorkingDirectory=$review;$si.UseShellExecute=$false;$si.CreateNoWindow=$true;$si.RedirectStandardOutput=$true;$si.RedirectStandardError=$true
foreach($a in @('--model','gemini-3.8-flash-high','--mode','plan','--sandbox','--new-project','--disable-slash-commands','--output-format','json','--print-timeout','210s','--json-schema',$schemaPath,'--log-file',(Join-Path $review 'provider.log'),'--print',$prompt)){$si.ArgumentList.Add($a)}
$p=[Diagnostics.Process]::new();$p.StartInfo=$si;$watch=[Diagnostics.Stopwatch]::StartNew();$p.Start()|Out-Null
@{pid=$p.Id;model='gemini-3.8-flash-high';provider_deadline=210;outer_deadline=240;credential_saved=$false}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $review 'launch.json')
$ot=$p.StandardOutput.ReadToEndAsync();$et=$p.StandardError.ReadToEndAsync();$killed=$false
while(!$p.WaitForExit(15000)){@{seconds=[math]::Round($watch.Elapsed.TotalSeconds);state='waiting'}|ConvertTo-Json -Compress|Add-Content -LiteralPath (Join-Path $review 'heartbeat.jsonl');if($watch.Elapsed.TotalSeconds -ge 240){$p.Kill($true);$killed=$true;break}}
$p.WaitForExit();$stdout=$ot.GetAwaiter().GetResult();$stderr=$et.GetAwaiter().GetResult();$stdout|Set-Content -LiteralPath (Join-Path $review 'stdout.json');$stderr|Set-Content -LiteralPath (Join-Path $review 'stderr.txt');$state='NOT_ACCEPTED'
try{$r=$stdout|ConvertFrom-Json;$usage=$r.usage;$answer=$r.response;if($answer -isnot [string]){$answer=$answer|ConvertTo-Json -Depth 25};$parsed=$answer|ConvertFrom-Json;if(!$killed -and $p.ExitCode -eq 0 -and $null -ne $parsed.findings){$parsed|ConvertTo-Json -Depth 25|Set-Content -LiteralPath (Join-Path $review 'review.json');$state='COMPLETE_REVIEW_PENDING_ADJUDICATION'}}catch{}
@{requested_model='gemini-3.8-flash-high';status=$state;pid=$p.Id;exit_code=$p.ExitCode;elapsed_seconds=[math]::Round($watch.Elapsed.TotalSeconds,2);outer_killed=$killed;usage=$usage}|ConvertTo-Json -Depth 10|Set-Content -LiteralPath (Join-Path $review 'terminal.json')

